    public function setrdConstruct($apicfgs,$setrd_datas){
        $hitcfg=null;
        $gid = $this->getGameIdByGameCode($setrd_datas['param']['gamecode']);
        if ($gid){
            $hitcfg=Games::getConfigs($gid);
            $this->tcid = $hitcfg['g_tcid'];
        }
        //结束
        parent::setrdConstruct($hitcfg,$setrd_datas); // TODO: Change the autogenerated stub
    }

    /**
     * @inheritDoc
     */
    function transOtherKvs(&$kvs)
    {
        $config = $this->apicfgs;
        $user = $config['trdcfg']['tc_api_signkey'].':'.$config['trdcfg']['tc_api_prikey'];
        $basic = 'Basic '.base64_encode($user);
        $kvs['Authorization'] = $basic;

        if($kvs['runfunc'] == 'GETUSERURL') {
            $uid = $kvs['uid'];
            $uname = Meta::initGetField('uname', $config['g_tcid'], $config['g_id'], $uid);
            $kvs['language'] = $config['trdcfg']['tc_langmap'];
            $kvs['playerid'] = $uname;
            $kvs['currency'] = $config['trdcfg']['tc_currency'];
            $kvs['externalsessionid'] = md5($uname.time());
            $kvs['ipaddress'] = Utils::get_ip();
            $kvs['country'] = $config['trdcfg']['tc_token'];
        }

        if($kvs['runfunc'] == 'GIVEFREEBETS') {
            if(isset($kvs['freesn'])){
                $kvs['validhours'] = abs($kvs['freebetEndtime'] - $kvs['freebetStarttime']) / 3600;
                //$kvs['brand'] = $config['trdcfg']['tc_tag'];
                //$kvs['externalfreebetid'] = $kvs['freesn'];
                //不需要转汇率了，封装中已经处理
                //$kvs['freebetPriceCnt'] = Third::transExchangerate($kvs['freebetPriceCnt_bak'], 1, 0);


            }
        }

        // TODO: Implement transOtherKvs() method.
    }


