    //根据gameCode获取游戏id
    public function getGameIdByGameCode($gameCode = ''){
        if( !$gameCode ){
            return 0;
        }
        $gameCodeArr = explode('_', $gameCode);;
        $thirdName = strtoupper($gameCodeArr[0]);
        //获取平台id
        $tcId = ThirdConfigs::where('tc_code', '=', $thirdName.'GAMETECHAPI')->value('tc_id');
        return Game::getGamesInfoBy($tcId, $gameCode, 'code', 'g_id');
    }

